code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]

    candidates = [
        ("row", lambda r, c: r),
        ("down_right", lambda r, c: c-r),
        ("down_left", lambda r, c: c+r),
    ]
    best = None
    for name, keyfn in candidates:
        groups = {}
        for r, c, color in cells:
            groups.setdefault(keyfn(r, c), set()).add(color)
        monochrome = [k for k, colors in groups.items() if len(colors) == 1]
        covered = sum(sum(1 for r, c, _ in cells if keyfn(r, c) == k) for k in monochrome)
        score = (covered, len(monochrome))
        if best is None or score > best[0]:
            best = (score, name, keyfn, groups)

    _, _, keyfn, groups = best
    known = {k: next(iter(colors)) for k, colors in groups.items() if len(colors) == 1}
    period = next(p for p in range(1, max(h, w) + 1)
                  if all(not any((k % p) == (j % p) and color != other
                                 for j, other in known.items())
                         for k, color in known.items()))
    residues = {}
    for k, color in known.items():
        residues[k % period] = color
    # Missing pattern positions inherit the preceding color in the repeating cycle.
    for i in range(period):
        if i not in residues:
            for step in range(1, period + 1):
                prev = (i - step) % period
                if prev in residues:
                    residues[i] = residues[prev]
                    break
    return [[residues[keyfn(r, c) % period] for c in range(w)] for r in range(h)]
'''
